import {archivedQuestions} from './archived-questions.js';
import {bankStats} from './bank-stats.js';
import {predictScores} from './irt.js';
import {buildStudyPlan} from './plan.js';
import {loadRoster,saveRoster,createStudent,normalizeStudent,importStudent} from './profiles.js';
import {sessionAnalytics,classifyError} from './analytics.js';
import {equationBlock,predictionPanel,personalizedHome,renderPlanPage,renderTutorPage,analyticsPanel,guidePage} from './features.js';
import {toolkit,calculatorHTML,referenceHTML,highlightedPassage,calculate} from './exam-tools.js';
import {initialState,STORAGE_KEY,XP_PER_LEVEL,dateKey,streak,reconcileFreezes,noteActivity,awardXp,updateElo,scheduleReview,adaptiveQuestions,dailyQuestions,shuffled,buildTutorPayload,reviewAllowed} from './learning.js';

const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',bank:'M4 4h6v7H4zM14 4h6v7h-6zM4 15h6v5H4zM14 15h6v5h-6z',cards:'M7 3h13v16H7zM4 6v15h13',bolt:'m13 2-9 12h7l-1 8L21 9h-8Z',chart:'M4 20V10m6 10V4m6 16v-8m5 8H2',chat:'M21 11a8 8 0 0 1-8 8H7l-5 3 2-6a8 8 0 1 1 17-5Z',trophy:'M8 3h8v5a4 4 0 0 1-8 0ZM8 5H4v2a4 4 0 0 0 4 4m8-6h4v2a4 4 0 0 1-4 4m-4 1v5m-4 3h8m-6-3h4',arrow:'M5 12h14m-5-5 5 5-5 5',back:'M19 12H5m5-5-5 5 5 5',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',search:'M21 21l-5-5m2-6a7 7 0 1 1-14 0 7 7 0 0 1 14 0',bookmark:'M6 3h12v18l-6-4-6 4Z',fire:'M13 2c2 6-1 7 2 9 2-1 3-3 3-3s5 7 1 12a8 8 0 0 1-12-1C2 13 8 7 8 7s-1 5 2 5c3-3 0-6 3-10Z',star:'m12 3 2.8 5.7 6.3.9-4.6 4.4 1.1 6.3-5.6-3-5.6 3 1.1-6.3L3 9.6l6.2-.9Z',snow:'M12 2v20M3.3 7l17.4 10M3.3 17 20.7 7m-12-3L12 7l3.3-3M8.7 20 12 17l3.3 3M3.5 11 7 10l-1-3M18 17l-1-3 3.5-1M3.5 13 7 14l-1 3M18 7l-1 3 3.5 1',target:'M12 4a8 8 0 1 0 8 8m-8-4a4 4 0 1 0 4 4m-4 0L22 2m-6 0h6v6',clock:'M12 8v5l3 2m6-3a9 9 0 1 1-18 0 9 9 0 0 1 18 0',info:'M12 11v6m0-10v.01m9 5a9 9 0 1 1-18 0 9 9 0 0 1 18 0',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3l-1 3-3 1-2 4 2 2v4l4 2 3-1 3 1 4-2v-4l2-2-2-4-3-1-1-3Z',math:'M5 5h14M5 19h14m-6-9-4 4m0-4 4 4',book:'M12 6C8 3 4 4 2 5v15c4-2 7-1 10 1 3-2 6-3 10-1V5c-3-1-6-2-10 1Zm0 0v15',menu:'M4 6h16M4 12h16M4 18h16',spark:'m12 3 2 7 7 2-7 2-2 7-2-7-7-2 7-2Zm8-2v4m-2-2h4',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',link:'m10 14 4-4m-7 5-2 2a4 4 0 0 0 6 5l4-4a4 4 0 0 0 0-6m2-3 2-2a4 4 0 0 0-6-5l-4 4a4 4 0 0 0 0 6',rocket:'M14 4c3-2 7-2 7-2s0 4-2 7l-7 7-5-5Zm-7 7-4 1-1 5 5-1m5 0-1 5 5-1 1-4M5 19l-2 2m13-14h.01',volume:'M5 9H2v6h3l5 4V5Zm10-1a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]??paths.star}"/></svg>`;
const logo=`<svg viewBox="0 0 40 40" class="orbit-logo" aria-hidden="true"><circle cx="20" cy="20" r="10" fill="currentColor"/><ellipse cx="20" cy="20" rx="19" ry="7" transform="rotate(-38 20 20)" fill="none" stroke="currentColor" stroke-width="2.6"/><circle cx="34" cy="9" r="2.7" fill="#d0c3ff"/></svg>`;
let state=initialState();
try {const saved=JSON.parse(localStorage.getItem(STORAGE_KEY));if(saved?.version===1)state={...state,...saved};}catch{}
let roster=loadRoster(localStorage,state);
state=roster.students.find(s=>s.id===roster.activeId).data;
if(state.name!=='You')state.onboarded=true;
let planOffset=0,tutorSelectedId=null,guideTab='math',highlightSelection=null,toolLastFocus=null;
function readRoute(){return location.hash.slice(1)||({plan:'plan',tutor:'tutor',guide:'guide',go:'home'})[location.pathname.split('/').filter(Boolean)[0]]||'home';}
let themePreference='dark';try{themePreference=localStorage.getItem('orbit-ui-theme')||'dark';}catch{}
function applyTheme(value=themePreference){themePreference=value;const resolved=value==='system'?(window.matchMedia?.('(prefers-color-scheme: light)').matches?'light':'dark'):value;document.documentElement.dataset.theme=resolved;document.querySelector('meta[name=theme-color]')?.setAttribute('content',resolved==='light'?'#f5f6fa':'#0c0f18');try{localStorage.setItem('orbit-ui-theme',value);}catch{}}
applyTheme();
const freezeUsed=reconcileFreezes(state);
let view=readRoute(),filters={subject:'All',difficulty:'All',domain:'All',search:'',saved:'all',page:1},historyPage=1,historyFilter='all',historyTab='attempts',boardScope='week',cardIndex=0,cardFlipped=false,cardDeck='all',practice=null,practiceTimer=null,lastFocused=null,toastTimer,installPrompt=null,chatMessages=[];
let tutorWorker=null,teachWorker=null;
function resetTutorWorkers(){tutorWorker?.terminate?.();teachWorker?.terminate?.();try{tutorWorker=new Worker('/tutor-worker.js',{type:'module'});teachWorker=new Worker('/tutor-worker.js?mode=teach',{type:'module'});}catch{}}
resetTutorWorkers();
function save(){try{state.prediction=predictScores(state.log,questions);state.runtimeStats={...bankStats,prediction:state.prediction,profile:{id:roster.activeId,name:state.name},updatedAt:new Date().toISOString()};saveRoster(localStorage,roster,state);localStorage.setItem(STORAGE_KEY,JSON.stringify(state));localStorage.setItem('orbit-runtime-stats-'+roster.activeId,JSON.stringify(state.runtimeStats));}catch{toast('Storage is full or unavailable. Export your profile to keep a copy.');}}

const completed=()=>questions.filter(q=>state.answers[q.id]?.completed).length;
const correctCount=()=>questions.filter(q=>state.answers[q.id]?.everCorrect).length;
const accuracy=()=>state.log.length?Math.round(state.log.filter(a=>a.correct).length/state.log.length*100):0;
const level=()=>Math.floor(state.xp/XP_PER_LEVEL)+1;
const byId=id=>questions.find(q=>q.id===id)||archivedQuestions.find(q=>q.id===id);
const todayLog=()=>state.log.filter(a=>dateKey(new Date(a.ts))===dateKey());
const dateLabel=ts=>new Date(ts).toLocaleDateString(undefined,{month:'short',day:'numeric'});
const xpToday=()=>state.xpEvents.filter(e=>dateKey(new Date(e.ts))===dateKey()).reduce((s,e)=>s+e.amount,0);
const dueCount=()=>Object.values(state.schedule).filter(s=>s.due<=Date.now()).length;
save();
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function setView(next){if(practice)return;history.pushState({},'', ['plan','tutor','guide'].includes(next)?'/'+next:'/#'+next);view=next;if($('.modal'))closeModal();renderApp();window.scrollTo(0,0);}

function pageIntro(eyebrow,title,sub,extra=''){return `<div class="page-intro"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>${extra}</div>`;}
function pill(label,color=''){return `<span class="pill ${color}">${label}</span>`;}
function progressBar(n,total,cls=''){return `<div class="progress-bar ${cls}"><span style="width:${Math.min(100,total?n/total*100:0)}%"></span></div>`;}
function orbitArt(){return `<svg class="hero-art" viewBox="0 0 440 310" role="img" aria-label="A small rocket setting off around an orbiting planet"><defs><radialGradient id="planet"><stop stop-color="#b8a2f9"/><stop offset="1" stop-color="#7565c0"/></radialGradient><linearGradient id="exhaust" x2="0" y2="1"><stop stop-color="#d8f99a"/><stop offset="1" stop-color="#c1e987" stop-opacity="0"/></linearGradient></defs><circle cx="258" cy="149" r="130" fill="none" stroke="#bca6ff" stroke-opacity=".12"/><ellipse cx="255" cy="150" rx="184" ry="68" transform="rotate(-28 255 150)" fill="none" stroke="#b7a0ff" stroke-opacity=".3" stroke-dasharray="3 7"/><circle cx="251" cy="149" r="80" fill="url(#planet)"/><path d="M186 103c27 8 52 15 89 11m-101 21c32 18 70 24 113 21m-104 23c28 15 60 21 93 19" fill="none" stroke="#d5c6ff" stroke-width="11" opacity=".12"/><ellipse cx="251" cy="149" rx="130" ry="26" transform="rotate(-28 251 149)" fill="none" stroke="#c8f29a" stroke-width="14"/><path d="M136 201c9 20 66 8 129-25" fill="none" stroke="#deffb5" stroke-width="14"/><circle cx="353" cy="67" r="17" fill="#f48d73"/><circle cx="347" cy="63" r="4" fill="#d46b59" opacity=".5"/><path d="m117 69 4 8 9 1-7 6 2 9-8-4-8 4 2-9-7-6 9-1Z" fill="#d3f6a9"/><path d="m369 227 2 6 6 2-6 2-2 6-2-6-6-2 6-2Z" fill="#a99bdc"/><g transform="translate(86 190) rotate(-28)"><path d="M0 28c-5 23 2 44 2 44s10-20 8-42" fill="url(#exhaust)"/><path d="M-10 21-20 36l12-1M11 21l11 15-14-1" fill="#c4b8ff"/><path d="M1-20C-14-4-13 17-9 32h20C15 15 14-6 1-20" fill="#f2f1ff"/><path d="M1-20C-4-15-7-9-8-4h18C8-10 5-15 1-20" fill="#c7f19d"/><circle cx="1" cy="9" r="6" fill="#222942" stroke="#9e91d6" stroke-width="2"/><path d="M-7 32H9" stroke="#9e91d6" stroke-width="4"/></g><g fill="#e4ddfa"><circle cx="60" cy="95" r="1.5"/><circle cx="172" cy="43" r="2"/><circle cx="394" cy="139" r="2"/><circle cx="310" cy="264" r="1.5"/><circle cx="188" cy="268" r="2"/><circle cx="408" cy="46" r="1.3"/></g><g transform="translate(323 172) rotate(9)"><rect width="74" height="54" rx="13" fill="#272640" stroke="#686080"/><text x="37" y="35" text-anchor="middle" fill="#d9ceff" font-family="Georgia,serif" font-size="28" font-style="italic">x²</text></g></svg>`;}

const navItems=[['home','home','Mission control'],['plan','clock','My study plan'],['bank','bank','Question bank','500'],['cards','cards','Flashcards'],['challenges','bolt','Challenges','2×'],['coach','chat','Orbit tutor'],['progress','chart','Your progress'],['leaderboard','trophy','Leaderboard'],['guide','book','Rules & formulas'],['tutor','target','Tutor dashboard']];
const titles={home:'Overview',bank:'Question bank',cards:'Flashcards',challenges:'Challenges',coach:'Orbit tutor',progress:'Your progress',leaderboard:'Leaderboard',science:'The study lab',plan:'My study plan',tutor:'Tutor dashboard',guide:'Rules & formulas'};
function renderApp(){
 if(!titles[view])view='home';
 $('#app').innerHTML=`<aside class="sidebar" id="sidebar"><a href="#home" class="brand">${logo}<span>orbit<span class="brand-dot">.</span></span><span class="beta">SAT</span></a><div class="nav-label">YOUR LAUNCHPAD</div><nav aria-label="Main navigation">${navItems.map(([key,ic,text,badge],i)=>`${i===5?'<div class="nav-divider"></div><div class="nav-label">LEVEL UP</div>':''}<a href="${['plan','tutor','guide'].includes(key)?'/'+key:'#'+key}" data-route="${key}" class="nav-item ${view===key?'active':''}" ${view===key?'aria-current="page"':''}>${icon(ic)}<span>${text}</span>${badge?`<small class="nav-badge ${key==='challenges'?'green':''}">${badge}</small>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><a class="study-lab" href="#science">${icon('spark')}<span>Better learning, by design</span>${icon('chevron')}</a><div class="level-card"><div class="level-card-top"><span class="level-emblem">${icon('rocket')}</span><div><strong>Level ${level()}</strong><span>${level()<3?'Space cadet':level()<7?'Pathfinder':'Trailblazer'}</span></div><span class="level-xp">${state.xp%XP_PER_LEVEL}<small> / ${XP_PER_LEVEL} XP</small></span></div>${progressBar(state.xp%XP_PER_LEVEL,XP_PER_LEVEL)}<div class="level-caption">${XP_PER_LEVEL-state.xp%XP_PER_LEVEL} XP to your next level</div></div><button class="profile" data-action="settings"><span class="avatar">${esc(state.name.charAt(0).toUpperCase())}</span><span><strong>${esc(state.name==='You'?'Your space':state.name)}</strong><small>Big things ahead</small></span>${icon('settings')}</button></div></aside><div class="main-shell"><header class="topbar"><button class="icon-button mobile-menu" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button><div class="breadcrumb">Your workspace <span>/</span> <strong>${titles[view]}</strong></div><div class="topbar-right"><button class="theme-toggle" data-action="theme" aria-label="Switch to ${document.documentElement.dataset.theme==='dark'?'light':'dark'} mode">${document.documentElement.dataset.theme==='dark'?'☀':'☾'}</button><button class="active-student-chip" data-action="profiles">${esc(state.name)} ▾</button><span class="streak-chip" title="Current study streak">${icon('fire')}<b>${streak(state)}</b><span>day streak</span></span><button class="freeze-chip" data-action="freezes" aria-label="${state.freezes} streak freezes available">${icon('snow')} ${state.freezes}</button><span class="topbar-divider"></span><button class="goal-chip" data-action="settings">${icon('target')}<span>Goal <b>${state.goal}</b></span></button><button class="icon-button" data-action="help" aria-label="Help and keyboard shortcuts">${icon('info')}</button></div></header><main id="main" tabindex="-1">${({home:renderHome,bank:renderBank,cards:renderCards,challenges:renderChallenges,coach:renderCoach,progress:()=>renderProgress()+predictionPanel(state,questions),leaderboard:renderLeaderboard,science:renderScience,plan:()=>renderPlanPage(state,questions,planOffset),tutor:()=>renderTutorPage(roster,questions,tutorSelectedId),guide:()=>guidePage(guideTab)}[view])()}</main><footer class="app-footer"><span><span class="tiny-star">✦</span> Built for curious minds. Made for the climb.</span><button data-action="about">About Orbit ${icon('arrow')}</button></footer></div>`;
 if(view==='coach')scrollChat();
}
function renderHome(){
 const dailyDone=state.sessions.some(s=>s.mode==='daily'&&dateKey(new Date(s.ts))===dateKey()&&s.finished);
 const bossDone=state.sessions.some(s=>s.mode==='boss'&&dateKey(new Date(s.ts))===dateKey()&&s.correct===5);
 const reviews=state.reviews.filter(r=>dateKey(new Date(r.ts))===dateKey()).length;
 const mathDone=questions.filter(q=>q.subject==='Math'&&state.answers[q.id]?.completed).length;
 const rwDone=completed()-mathDone;
 return `${pageIntro(`WELCOME ${state.sessions.length?'BACK, ':'TO ORBIT, '}${esc(state.name.toUpperCase())}`,'Small steps. Stellar scores.','Big goals feel closer when you make a little progress every day.',`<div class="live-label"><span></span> YOUR NEXT CHAPTER STARTS HERE</div>`)}<div class="dashboard-top"><section class="hero-card"><div class="hero-copy"><div class="hero-tag">${icon('rocket')} MISSION: YOUR PERSONAL BEST</div><h2>Aim high.<br>Start small.</h2><p>500 questions. A universe of potential.<br>Your next level is one good session away.</p><button class="button primary" data-action="practice">Let’s practice ${icon('arrow')}</button><span class="hero-caption">10 adaptive questions · No pressure, just progress</span></div>${orbitArt()}<div class="art-caption"><span></span> YOU ARE HERE. KEEP GOING.</div></section><section class="momentum-card panel"><div class="panel-heading"><h2>Your momentum</h2>${pill('ALL TIME')}</div><div class="progress-orbit" style="--progress:${completed()/5}%"><div><strong>${completed()}</strong><span>of 500 completed</span></div><i class="orbit-point"></i></div><p class="momentum-caption">${completed()?'Look at you, building momentum.':'Every great journey starts at zero.'}</p><div class="mini-stats"><div><span class="stat-symbol mint">${icon('bolt')}</span><strong>${state.xp.toLocaleString()}</strong><small>Total XP</small></div><div><span class="stat-symbol lavender">${icon('target')}</span><strong>${state.log.length?accuracy()+'%':'—'}</strong><small>Accuracy</small></div><div><span class="stat-symbol peach">${icon('fire')}</span><strong>${streak(state)}</strong><small>Day streak</small></div></div></section></div>${personalizedHome(state,questions)}<section class="focus-section"><div class="section-heading"><div><h2>Find your focus</h2><p>Pick a path. Make it yours.</p></div><a href="#bank" class="text-link">Explore the question bank ${icon('arrow')}</a></div><div class="focus-grid"><button class="focus-card math-card" data-action="subject-practice" data-subject="Math"><div class="focus-card-top"><span class="subject-icon mint">${icon('math')}</span>${pill('300 QUESTIONS')}</div><h3>Math, minus the mystery.</h3><p>Build confidence, one “got it” at a time.</p><div class="focus-card-bottom"><span>${mathDone}<small> / 300 complete</small></span>${icon('arrow')}</div>${progressBar(mathDone,300)}</button><button class="focus-card reading-card" data-action="subject-practice" data-subject="Reading & Writing"><div class="focus-card-top"><span class="subject-icon lavender">${icon('book')}</span>${pill('200 QUESTIONS')}</div><h3>Read it. Get it. Own it.</h3><p>Sharpen your reading and writing instincts.</p><div class="focus-card-bottom"><span>${rwDone}<small> / 200 complete</small></span>${icon('arrow')}</div>${progressBar(rwDone,200,'purple')}</button><button class="focus-card sprint-card" data-action="daily"><div class="focus-card-top"><span class="subject-icon peach">${icon('bolt')}</span>${pill(dailyDone?'COMPLETED':'2× XP','peach-pill')}</div><h3>Your daily launch.</h3><p>10 mixed questions. A fresh challenge daily.</p><div class="focus-card-bottom"><span>${dailyDone?'Go again':'Take the challenge'}</span>${icon('arrow')}</div><div class="sprint-line"><span>✦</span> SMALL WINS. BIG ENERGY.</div></button></div></section><div class="dashboard-bottom"><section class="panel quest-panel"><div class="section-heading"><div><h2>A little extra motivation</h2><p>Your quests reset every day.</p></div>${pill(`${Number(dailyDone)+Number(bossDone)+Number(reviews>=3)} / 3 DONE`)}</div>${questRow('Complete your Daily Challenge','10 questions from across the galaxy',dailyDone,'2× XP','daily')}${questRow('Face a Boss Fight','5 past mistakes. One fresh start.',bossDone,'+75 XP','boss')}${questRow('Review 3 flashcards',`${Math.min(3,reviews)} of 3 reviewed today`,reviews>=3,'+30 XP','go-cards')}</section><section class="coach-promo"><div class="coach-orb">${icon('chat')}<span>✦</span></div><div>${pill('YOUR THINKING PARTNER','purple-pill')}<h2>A little stuck?<br>Take a hint.</h2><p>Concept first. A nudge next.<br>The discovery is still yours.</p><a href="#coach" class="button secondary">Meet Orbit tutor ${icon('arrow')}</a></div><span class="promo-star">✧</span></section></div>`;
}
function questRow(title,sub,done,reward,action){return `<button class="quest-row" data-action="${action}"><span class="quest-check ${done?'done':''}">${done?icon('check'):''}</span><span><strong>${title}</strong><small>${sub}</small></span><span class="quest-reward ${done?'complete':''}">${done?icon('check'):icon('bolt')}${reward}</span></button>`;}
function filteredBank(){return questions.filter(q=>(filters.subject==='All'||q.subject===filters.subject)&&(filters.difficulty==='All'||q.difficulty===filters.difficulty)&&(filters.domain==='All'||q.domain===filters.domain)&&(filters.saved==='all'||filters.saved==='saved'&&state.bookmarks.includes(q.id)||filters.saved==='missed'&&state.answers[q.id]?.failedAttempts>0||filters.saved==='marked'&&state.markedForReview.includes(q.id))&&(!filters.search||`${q.id} ${q.prompt} ${q.passage} ${q.skill} ${(q.equations??[]).join(' ')}`.toLowerCase().includes(filters.search.toLowerCase())));}
function renderBank(){return `${pageIntro('THE QUESTION UNIVERSE','Curiosity looks good on you.','500 original SAT-style questions. Find your next breakthrough.',`<button class="button primary" data-action="filtered-practice">Practice this set ${icon('arrow')}</button>`)}<div class="panel bank-controls"><div class="subject-tabs" role="group" aria-label="Subject filter">${['All','Math','Reading & Writing'].map(s=>`<button data-action="filter-subject" data-subject="${esc(s)}" class="${filters.subject===s?'active':''}">${s==='All'?'All questions':s}<span>${s==='All'?500:s==='Math'?300:200}</span></button>`).join('')}</div><div class="filter-row"><label class="search-field">${icon('search')}<input id="bank-search" type="search" placeholder="Search questions, skills, or IDs…" value="${esc(filters.search)}" aria-label="Search questions"></label><select id="difficulty-filter" aria-label="Difficulty"><option value="All">All difficulties</option>${['Easy','Medium','Hard'].map(d=>`<option ${filters.difficulty===d?'selected':''}>${d}</option>`).join('')}</select><select id="domain-filter" aria-label="Domain"><option value="All">All topics</option>${[...new Set(questions.filter(q=>filters.subject==='All'||q.subject===filters.subject).map(q=>q.domain))].map(d=>`<option ${filters.domain===d?'selected':''}>${d}</option>`).join('')}</select></div></div><div id="bank-results">${renderBankResults()}</div>`;}
function renderBankResults(){const all=filteredBank(),pages=Math.max(1,Math.ceil(all.length/10));filters.page=Math.min(filters.page,pages);const subset=all.slice((filters.page-1)*10,filters.page*10);return `<div class="bank-result-toolbar"><div class="filter-pills">${[['all','All questions'],['saved',`Saved · ${state.bookmarks.length}`],['missed',`Missed · ${Object.values(state.answers).filter(a=>a.failedAttempts>0).length}`],['marked',`Marked · ${state.markedForReview.length}`]].map(([key,title])=>`<button data-action="filter-saved" data-key="${key}" class="${filters.saved===key?'active':''}">${title}</button>`).join('')}</div><div class="bank-tools"><span class="muted small">${all.length} questions</span>${filters.search||filters.subject!=='All'||filters.domain!=='All'||filters.difficulty!=='All'||filters.saved!=='all'?'<button class="clear-filters" data-action="clear-filters">Reset filters</button>':''}</div></div><div class="question-list">${subset.length?subset.map(q=>`<div class="question-row"><button class="question-open" data-action="open-question" data-id="${q.id}"><span class="question-type ${q.subject==='Math'?'mint':'lavender'}">${icon(q.subject==='Math'?'math':'book')}</span><span class="question-preview"><span class="question-meta">${q.id}<i>·</i>${q.skill}</span><strong>${esc(q.prompt)}</strong><span class="question-excerpt">${esc(q.passage||(q.equations?.join(' · '))||q.domain)}</span></span><span class="difficulty ${q.difficulty.toLowerCase()}">${q.difficulty}</span>${state.answers[q.id]?.everCorrect?`<span class="mastered-marker" title="Solved">${icon('check')}</span>`:icon('chevron')}</button><button class="icon-button save-question ${state.bookmarks.includes(q.id)?'saved':''}" data-action="bookmark" data-id="${q.id}" aria-label="${state.bookmarks.includes(q.id)?'Unsave':'Save'} question ${q.id}" aria-pressed="${state.bookmarks.includes(q.id)}">${icon('bookmark')}</button></div>`).join(''):`<div class="empty-state">${icon('search')}<h3>A little empty out here.</h3><p>Try a different search or clear your filters.</p><button class="button secondary" data-action="clear-filters">Clear filters</button></div>`}</div><div class="pagination"><span>Showing ${all.length?(filters.page-1)*10+1:0}–${Math.min(filters.page*10,all.length)} of ${all.length}</span><div><button class="icon-button" data-action="bank-page" data-offset="-1" ${filters.page<=1?'disabled':''} aria-label="Previous page">${icon('back')}</button><span>${filters.page} / ${pages}</span><button class="icon-button" data-action="bank-page" data-offset="1" ${filters.page>=pages?'disabled':''} aria-label="Next page">${icon('arrow')}</button></div></div>`;}
function getCardDeck(){return questions.filter(q=>cardDeck==='all'||cardDeck==='saved'&&state.bookmarks.includes(q.id)||cardDeck==='due'&&state.schedule[q.id]?.due<=Date.now()||cardDeck==='missed'&&state.answers[q.id]?.failedAttempts>0);}
function renderCards(){const deck=getCardDeck();cardIndex=deck.length?cardIndex%deck.length:0;const q=deck[cardIndex];return `${pageIntro('FLIP YOUR PERSPECTIVE','Make it stick.','Recall it first. Flip it second. Come back when it’s due.',`<select id="card-deck" aria-label="Flashcard deck">${[['all','All 500 questions'],['due',`Due for review (${dueCount()})`],['saved','Saved questions'],['missed','Previously missed']].map(([v,l])=>`<option value="${v}" ${v===cardDeck?'selected':''}>${l}</option>`).join('')}</select>`)}${q?`<div class="flashcard-wrap"><div class="flashcard-toolbar"><span>${q.skill}</span><span>${cardIndex+1} / ${deck.length}</span><button class="icon-button ${state.bookmarks.includes(q.id)?'saved':''}" data-action="bookmark" data-id="${q.id}" aria-label="Save flashcard">${icon('bookmark')}</button></div><button class="flashcard ${cardFlipped?'flipped':''}" data-action="flip-card" aria-label="${cardFlipped?'Show question':'Reveal answer'}"><div class="flashcard-face"><div class="eyebrow">${cardFlipped?'THE CLICK MOMENT':`${q.id} · THINK IT THROUGH`}</div>${cardFlipped?`<h2>${esc(q.choices[q.answer])}</h2><div class="card-explanation">${q.workedSteps.map((s,i)=>`<p><span>${i+1}</span>${esc(s)}</p>`).join('')}</div>`:`${q.passage?`<p class="card-passage">${esc(q.passage)}</p>`:''}${equationBlock(q)}<h2>${esc(q.prompt)}</h2>`}<span class="flip-caption">${icon('cards')} ${cardFlipped?'Tap to see the question':'Try to recall, then tap to reveal'} <kbd>Space</kbd></span></div></button><div class="flashcard-actions"><button class="icon-button" data-action="card-prev" aria-label="Previous flashcard">${icon('back')}</button><button class="button secondary" data-action="review-card" data-result="again" ${!cardFlipped?'disabled':''}>Study again</button><button class="button primary" data-action="review-card" data-result="got" ${!cardFlipped?'disabled':''}>Got it ${icon('check')}</button><button class="icon-button" data-action="card-next" aria-label="Next flashcard">${icon('arrow')}</button></div><p class="center muted small">“Got it” schedules a later review. “Study again” keeps it due now.</p></div>`:`<div class="panel empty-state">${icon('cards')}<h2>No cards in this orbit yet.</h2><p>${cardDeck==='due'?'Your scheduled cards will appear here when they’re due.':'Save or practice some questions to build this deck.'}</p><a class="button primary" href="#bank">Explore questions ${icon('arrow')}</a></div>`}`;}
function renderChallenges(){const misses=Object.entries(state.answers).filter(([,a])=>a.failedAttempts>0).length,dailyDone=state.dailyAwards.includes(dateKey());const recent=state.sessions.slice().reverse().slice(0,5);return `${pageIntro('A NEW WAY TO LEVEL UP','A challenge worth showing up for.','A little pressure. A lot of possibility.')}<div class="challenge-grid"><section class="challenge-card daily-challenge"><div class="challenge-visual"><span class="challenge-ring"></span>${icon('bolt')}<span class="floating-star">✦</span></div><div class="challenge-copy">${pill(dailyDone?'TODAY: COMPLETED':'DOUBLE THE MOMENTUM','green-pill')}<h2>Daily Challenge</h2><p>A fresh set of 10 questions from 10 distinct skills. Same mission for everyone, new every day.</p><div class="challenge-facts"><span>${icon('bank')}10 questions</span><span>${icon('bolt')}${dailyDone?'1× replay XP':'2× XP'}</span><span>${icon('clock')}At your pace</span></div><button class="button primary" data-action="daily">${dailyDone?'Play again':'Start today’s challenge'} ${icon('arrow')}</button><small>Double XP applies to your first completed daily run.</small></div></section><section class="challenge-card boss-challenge"><div class="challenge-visual boss-visual"><span class="boss-face"><i></i><i></i></span><span class="boss-crown">♛</span></div><div class="challenge-copy">${pill(misses>=5?'YOUR REMATCH IS READY':`${misses} / 5 QUESTIONS TO UNLOCK`,'purple-pill')}<h2>Boss Fight</h2><p>Five questions you’ve missed before. Turn your old stumbling blocks into your next power-up.</p><div class="challenge-facts"><span>${icon('target')}5 rematches</span><span>${icon('bolt')}+75 bonus XP</span></div><button class="button ${misses>=5?'purple-button':'secondary'}" data-action="boss">${misses>=5?'Face the boss':'Build your comeback'} ${icon('arrow')}</button><small>Clear all five without reviewing a solution for a once-daily bonus.</small></div></section></div><section class="panel sprint-panel"><div><span class="subject-icon peach">${icon('clock')}</span><div><h3>Feeling quick? Try a timed sprint.</h3><p>10 adaptive questions. 10 minutes. A snapshot of your focus.</p></div></div><button class="button secondary" data-action="sprint">Start sprint ${icon('arrow')}</button></section><section class="panel recent-missions"><div class="section-heading"><h2>Your recent missions</h2><a href="#progress" class="text-link">All results ${icon('arrow')}</a></div>${recent.length?recent.map(s=>sessionRow(s)).join(''):'<div class="empty-inline">Your first mission is waiting. Let’s make it a good one.</div>'}</section>`;}
function sessionRow(s){return `<div class="session-row"><span class="session-symbol">${icon(s.mode==='boss'?'target':s.mode==='daily'?'bolt':'rocket')}</span><span><strong>${({daily:'Daily Challenge',boss:'Boss Fight',sprint:'Timed sprint',friend:'Friend challenge',plan:'Study plan',practice:'Adaptive practice'})[s.mode]??'Practice'}</strong><small>${dateLabel(s.ts)} · ${s.attempted}/${s.total} attempted${s.finished?'':' · ended early'}</small></span><button class="text-link session-report-link" data-action="session-report" data-session="${s.id}">Report ↗</button><span class="session-score">${s.firstTry}/${s.total}<small>first try</small></span><span class="mint-text">+${s.xp} XP</span></div>`;}
function renderCoach(){const wrong=[...state.log].reverse().find(l=>!l.correct);const q=wrong?byId(wrong.id):null;return `${pageIntro('YOUR THINKING PARTNER','The best answer starts with your thinking.','A nudge when you need one. Space to figure it out.',pill('ON-DEVICE · NO API KEYS','green-pill'))}<div class="tutor-layout"><section class="panel chat-panel"><div class="chat-header"><span class="tutor-avatar">${icon('spark')}</span><div><h2>Orbit tutor</h2><span><i></i> Adaptive, answer-blind hints</span></div><button class="icon-button" data-action="tutor-info" aria-label="How the tutor works">${icon('info')}</button></div><div class="chat-messages" id="chat-messages"><div class="chat-message assistant"><span class="message-avatar">✦</span><div><p>Hey, curious mind. I’m here to help you find your next step.</p><p>After a missed attempt, I can explain the concept, help find the mistake, then guide your first step. You do the discovering.</p></div></div>${chatMessages.map(m=>`<div class="chat-message ${m.role}">${m.role==='assistant'?'<span class="message-avatar">✦</span>':''}<div>${m.level?`<span class="hint-level">LEVEL ${m.level} · ${esc(m.title)}</span>`:''}<p>${esc(m.text).replace(/\n/g,'<br>')}</p></div></div>`).join('')}</div><div class="chat-suggestions"><button data-action="coach-plan">Build my study plan</button><button data-action="coach-how">How hints work</button>${q?`<button data-action="coach-teach" data-id="${q.id}" data-choice="${wrong.choice}">Explain like I’m teaching a 1st grader</button><button data-action="coach-hint" data-id="${q.id}" data-choice="${wrong.choice}">Hint on my last miss</button>`:''}</div><form id="coach-form" class="chat-input"><input id="coach-input" placeholder="Ask about your last missed Orbit question…" aria-label="Message your study tutor" autocomplete="off"><button class="send-button" aria-label="Send message">${icon('arrow')}</button></form><p class="chat-disclosure">Rule-based adaptive guidance. Open-ended generative AI is not connected.</p></section><aside class="tutor-aside"><section class="panel"><span class="subject-icon lavender">${icon('chat')}</span><h3>Hints, with a purpose.</h3><div class="hint-step"><b>01</b><span><strong>The big idea</strong><small>Recall the concept.</small></span></div><div class="hint-step"><b>02</b><span><strong>The sticking point</strong><small>Check your selected response.</small></span></div><div class="hint-step"><b>03</b><span><strong>A first step</strong><small>Build your own solution.</small></span></div><div class="tutor-note">The tutor never receives the answer key. Solution review unlocks after two missed attempts.</div></section>${q?`<section class="panel last-miss"><span class="eyebrow">PICK UP WHERE YOU LEFT OFF</span><h3>${esc(q.skill)}</h3><p>${esc(q.prompt)}</p><button class="text-link" data-action="open-question" data-id="${q.id}">Try it again ${icon('arrow')}</button></section>`:`<section class="panel"><span class="eyebrow">YOUR FIRST STEP</span><h3>Give it a try.</h3><p class="muted">Your tutor will have more to work with after your first practice attempt.</p><button class="button secondary" data-action="practice">Start practice ${icon('arrow')}</button></section>`}</aside></div>`;}
function chatAdd(role,text,extra={}){chatMessages.push({role,text,...extra});renderApp();}
function scrollChat(){const el=$('#chat-messages');if(el)el.scrollTop=el.scrollHeight;}
function studyPlan(){const rated=Object.entries(state.skillRatings).sort((a,b)=>a[1]-b[1]);const weak=rated.slice(0,2).map(([s])=>s);return state.log.length?`Here’s a plan based on your practice so far:\n1. Spend 5 minutes on ${weak.join(' and ')}. These have your lowest local skill ratings.\n2. Review ${dueCount()?`${dueCount()} due flashcards`:'three cards from your missed questions'}. Try recalling before flipping.\n3. Finish with a mixed 10-question session.\nYou’ve practiced on ${state.days.length} day${state.days.length===1?'':'s'}. A short return tomorrow is a useful next win.`:'Start with one mixed 10-question session. It gives your local adaptive engine a starting point. Then review three flashcards and return tomorrow for a short recall session. You don’t need a perfect run to make progress.';}

function renderProgress(){const skills=[...new Set(questions.map(q=>q.skill))];const domains=[...new Set(questions.map(q=>q.domain))];const badges=[['First ignition','Complete one question',completed()>=1,'rocket'],['Double digits','Solve 10 different questions',correctCount()>=10,'bolt'],['Orbit regular','Practice on 3 days',state.days.length>=3,'fire'],['Century club','Solve 100 different questions',correctCount()>=100,'star'],['Boss slayer','Clear a Boss Fight',state.sessions.some(s=>s.mode==='boss'&&s.correct===5),'target'],['Full constellation','Complete all 500 questions',completed()===500,'trophy']];return `${pageIntro('EVERY ATTEMPT COUNTS','Look how far you’re going.','Your real results, across every question and every mission.',`<button class="button secondary" data-action="export-progress">${icon('download')} Export progress</button>`)}<div class="stats-grid">${[['bank',completed(),'Questions completed','mint'],['target',state.log.length?accuracy()+'%':'—','Attempt accuracy','lavender'],['bolt',state.xp.toLocaleString(),'Total XP','peach'],['fire',streak(state),'Day streak','mint']].map(([i,n,l,c])=>`<div class="panel stat-card"><span class="subject-icon ${c}">${icon(i)}</span><strong>${n}</strong><span>${l}</span></div>`).join('')}</div><div class="progress-grid"><section class="panel domain-progress"><div class="section-heading"><h2>Your skill universe</h2><span class="muted small">${skills.length} skills · 8 domains</span></div>${domains.map(domain=>{const qs=questions.filter(q=>q.domain===domain),n=qs.filter(q=>state.answers[q.id]?.everCorrect).length;return `<div class="domain-row"><div><strong>${domain}</strong><span>${n} / ${qs.length} solved</span></div>${progressBar(n,qs.length,domain.includes('Ideas')||domain.includes('Conventions')?'purple':'')}</div>`;}).join('')}<details class="rating-details"><summary>See your adaptive skill ratings ${icon('down')}</summary><p>Local ELO estimates help choose your practice. They are not SAT scores.</p>${Object.entries(state.skillRatings).sort((a,b)=>a[1]-b[1]).map(([s,r])=>`<div><span>${esc(s)}</span><b>${r}</b></div>`).join('')||'<p>Complete a few questions to establish your starting ratings.</p>'}</details></section><section class="panel consistency-panel"><div class="section-heading"><h2>Showing up is a skill.</h2>${icon('fire')}</div><p>Your last 28 days, one small win at a time.</p><div class="activity-grid">${Array.from({length:28},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(27-i));const key=dateKey(d),n=state.log.filter(l=>dateKey(new Date(l.ts))===key).length;return `<span class="activity-cell ${n?'filled':''} ${state.frozenDays.includes(key)?'frozen':''}" title="${key}: ${n} attempts${state.frozenDays.includes(key)?' · streak freeze':''}"><span>${d.getDate()}</span></span>`;}).join('')}</div><div class="activity-legend"><span><i></i>Rest day</span><span><i class="filled"></i>Practice</span><span><i class="frozen"></i>Freeze</span></div><div class="freeze-summary">${icon('snow')}<div><strong>${state.freezes} streak freezes ready</strong><span>Protect an occasional missed day. Earn one back every 7 practice days, up to two.</span></div></div><div class="achievement-header"><h3>Your constellation</h3><span>${badges.filter(b=>b[2]).length} / ${badges.length}</span></div><div class="badge-grid">${badges.map(([name,sub,unlocked,i])=>`<div class="achievement ${unlocked?'unlocked':''}" title="${sub}"><span>${icon(i)}</span><strong>${name}</strong><small>${unlocked?'Unlocked':sub}</small></div>`).join('')}</div></section></div><section class="panel history-panel"><div class="section-heading"><div><h2>Every attempt. Every comeback.</h2><p>All of your practice problems and quiz results stay here.</p></div><div class="segmented"><button data-action="history-tab" data-tab="attempts" class="${historyTab==='attempts'?'active':''}">Problems</button><button data-action="history-tab" data-tab="sessions" class="${historyTab==='sessions'?'active':''}">Sessions</button></div></div>${renderHistory()}</section>`;}
function renderHistory(){if(historyTab==='sessions'){const all=state.sessions.slice().reverse();return all.length?all.map(sessionRow).join(''):'<div class="empty-inline">Your mission log is clear for launch. Start a session to fill it.</div>';}
 const all=state.log.slice().reverse().filter(a=>historyFilter==='all'||historyFilter==='correct'&&a.correct||historyFilter==='incorrect'&&!a.correct),pages=Math.max(1,Math.ceil(all.length/15));historyPage=Math.min(historyPage,pages);return `<div class="history-filter"><select id="history-filter" aria-label="Filter results">${[['all','Every attempt'],['correct','Correct responses'],['incorrect','Missed responses']].map(([v,t])=>`<option value="${v}" ${historyFilter===v?'selected':''}>${t}</option>`).join('')}</select><span>${all.length} attempts · ${state.reviews.length} flashcard reviews</span></div>${all.length?`<div class="table-scroll"><table><thead><tr><th>Question / skill</th><th>Your response</th><th>Result</th><th>XP</th><th>Date</th></tr></thead><tbody>${all.slice((historyPage-1)*15,historyPage*15).map(a=>{const q=byId(a.id);return `<tr><td><button class="history-question" data-action="open-question" data-id="${q.id}"><strong>${q.id}</strong><span>${esc(q.skill)}</span></button></td><td class="response-cell">${esc(q.choices[a.choice])}</td><td><span class="result-pill ${a.correct?'correct':'incorrect'}">${a.correct?'Correct':'Keep learning'}</span></td><td class="mint-text">+${a.xp}</td><td>${dateLabel(a.ts)}</td></tr>`;}).join('')}</tbody></table></div><div class="pagination"><span>Page ${historyPage} of ${pages}</span><div><button class="icon-button" data-action="history-page" data-offset="-1" ${historyPage===1?'disabled':''} aria-label="Previous results">${icon('back')}</button><button class="icon-button" data-action="history-page" data-offset="1" ${historyPage===pages?'disabled':''} aria-label="Next results">${icon('arrow')}</button></div></div>`:'<div class="empty-inline">Your first attempt starts your story. Let’s make it happen.</div>'}`;}

// TODO Firebase: replace these explicitly labeled demo competitors with authenticated
// Firestore session writes and server-validated aggregated scores. Never ship service keys.
const demoRivals=[{name:'Luna',initial:'L',xp:1840,week:620,color:'purple'},{name:'Atlas',initial:'A',xp:1510,week:540,color:'mint'},{name:'Nova',initial:'N',xp:1290,week:410,color:'peach'},{name:'Kai',initial:'K',xp:980,week:280,color:'blue'}];
function renderLeaderboard(){const start=new Date();start.setHours(0,0,0,0);start.setDate(start.getDate()-((start.getDay()+6)%7));const myXp=boardScope==='week'?state.xpEvents.filter(e=>e.ts>=+start).reduce((s,e)=>s+e.amount,0):state.xp;const board=[...demoRivals.map(r=>({...r,score:boardScope==='week'?r.week:r.xp,demo:true})),{name:state.name,initial:state.name.charAt(0).toUpperCase(),score:myXp,color:'you',demo:false}].sort((a,b)=>b.score-a.score);return `${pageIntro('A LITTLE FRIENDLY COMPETITION','Good company. Great momentum.','Your local game board. Bring your own main-character energy.',pill('LOCAL DEMO','purple-pill'))}<div class="leaderboard-layout"><section class="panel leaderboard-panel"><div class="section-heading"><div><h2>The orbit league</h2><p>Demo competitors + your real progress</p></div><div class="segmented"><button data-action="board-scope" data-scope="week" class="${boardScope==='week'?'active':''}">This week</button><button data-action="board-scope" data-scope="all" class="${boardScope==='all'?'active':''}">All time</button></div></div><div class="leaderboard-header"><span>RANK / EXPLORER</span><span>XP EARNED</span></div>${board.map((r,i)=>`<div class="leaderboard-row ${r.demo?'':'you-row'}"><span class="rank ${i===0?'first':''}">${i===0?icon('trophy'):String(i+1).padStart(2,'0')}</span><span class="rival-avatar ${r.color}">${esc(r.initial)}</span><span class="rival-name"><strong>${esc(r.name)} ${!r.demo?pill('YOU','green-pill'):''}</strong><small>${r.demo?'Demo competitor':'Your actual XP · this device'}</small></span><strong class="board-xp">${r.score.toLocaleString()}<small> XP</small></strong></div>`).join('')}<div class="board-notice">${icon('info')}This is a local demo. Competitors are illustrative; your scores are real. Results are saved in this browser and are not synced between people.</div></section><aside class="panel league-aside"><div class="league-trophy">${icon('trophy')}</div><span class="eyebrow">YOUR NEXT PERSONAL BEST</span><h2>The real win?<br>Showing up.</h2><p>A shared leaderboard can come later. Right now, you can challenge a friend to your exact question set after any session.</p><button class="button primary" data-action="daily">Earn some XP ${icon('arrow')}</button><button class="text-link" data-action="settings">Edit your player name ${icon('arrow')}</button></aside></div><section class="panel recent-missions"><div class="section-heading"><h2>Your saved session results</h2><span class="muted small">${state.sessions.length} missions</span></div>${state.sessions.length?state.sessions.slice().reverse().map(sessionRow).join(''):'<div class="empty-inline">Your first session earns your first spot.</div>'}</section>`;}
function renderScience(){return `${pageIntro('THE STUDY LAB','Built around how learning works.','Small design choices, grounded in established learning research.')}<div class="science-intro panel"><span class="subject-icon mint">${icon('spark')}</span><div><h2>Practice, recall, reflect, return.</h2><p>Orbit uses research-informed principles to shape practice. These studies support the principles; they do not establish a measured SAT-score benefit for Orbit itself.</p></div></div><div class="science-grid">${[
 ['01','Retrieval practice','Try before you reveal.','Recalling information can support later retention more effectively than repeatedly rereading it. Orbit asks you to attempt questions and recall flashcards before seeing the solution.','Roediger & Karpicke (2006), Psychological Science','https://doi.org/10.1111/j.1467-9280.2006.01693.x'],
 ['02','Distributed practice','Come back when it counts.','Spacing learning over time supports retention. Correct responses move cards through 1-, 3-, 7-, 14-, and 30-day intervals; mistakes return them to the due queue. These particular intervals are a simple product heuristic.','Cepeda et al. (2006), Psychological Bulletin','https://doi.org/10.1037/0033-2909.132.3.354'],
 ['03','Formative feedback','A next step beats a dead end.','Feedback can help when it is specific, supportive, and focused on the task. Orbit diagnoses a likely mistake and gives a first step before offering full review after two failed attempts. The two-attempt rule is a design choice, not a universally proven threshold.','Shute (2008), Review of Educational Research','https://doi.org/10.3102/0034654307313795'],
 ['04','Scaffolding','Just enough help to keep thinking.','Scaffolding offers support for a task while leaving meaningful work to the learner. Orbit moves from a concept to a mistake check to an initial action, without giving its tutor the answer key.','Wood, Bruner & Ross (1976), Journal of Child Psychology and Psychiatry','https://doi.org/10.1111/j.1469-7610.1976.tb00381.x']
 ].map(([n,name,title,body,cite,url])=>`<article class="panel science-card"><span class="science-number">${n}</span>${pill(name.toUpperCase())}<h2>${title}</h2><p>${body}</p><a href="${url}" target="_blank" rel="noopener noreferrer">${cite} ${icon('arrow')}</a></article>`).join('')}</div><section class="panel science-note"><h2>Adaptive, with a clear meaning.</h2><p>Orbit’s local ELO engine updates a skill estimate after a response and aims for practice with about a 70% predicted success rate, prioritizing due reviews. This is a transparent selection heuristic. Its ratings are local estimates, not a calibrated ability measure or an SAT score prediction.</p><p>The tutor is an on-device rule-based engine. It uses your selected incorrect response and an answer-free scaffold; no generative AI service is connected. The current bank includes original parameter variants and has automated structural and numeric checks. It has not been independently psychometrically validated.</p><button class="button secondary" data-action="practice">Put it into practice ${icon('arrow')}</button></section>`;}

function openModal(html,wide=false){lastFocused=document.activeElement;$('#app').inert=true;$('#modal-root').innerHTML=`<div class="modal-scrim"><section class="modal ${wide?'wide-modal':''}" role="dialog" aria-modal="true" aria-label="${practice?'Practice session':'Orbit dialog'}">${html}</section></div>`;document.body.classList.add('modal-open');requestAnimationFrame(()=>$('#modal-root button, #modal-root input')?.focus());}
function closeModal(){if(practice){finishPractice(false);return;}$('#modal-root').innerHTML='';$('#app').inert=false;document.body.classList.remove('modal-open');lastFocused?.focus?.();}
function modalHeader(title,sub=''){return `<div class="modal-header"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>`;}
function settings(){openModal(`${modalHeader('Make this space yours.','Your progress stays in this local profile.')}<form id="settings-form" class="settings-form"><label>Student name or nickname<input name="name" value="${esc(state.name)}" maxlength="40" required autocomplete="nickname"></label><label>Test date<input name="testDate" type="date" value="${esc(state.testDate||'')}"></label><label>Your SAT goal<select name="goal">${[1200,1300,1400,1450,1500,1550,1600].map(n=>`<option ${state.goal===n?'selected':''}>${n}</option>`).join('')}</select></label><label>Appearance<select name="theme">${[['dark','Dark space'],['light','Light'],['system','Follow this device']].map(([v,t])=>`<option value="${v}" ${themePreference===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="toggle-row"><span><strong>Automatic streak protection</strong><small>Use a freeze for an occasional missed day.</small></span><input type="checkbox" name="freeze" ${state.autoFreeze?'checked':''}></label><button class="button primary" type="submit">Save my settings ${icon('check')}</button></form><div class="settings-install"><button class="button secondary" data-action="install">${icon('download')} Install Orbit</button><p>On iPhone: Safari → Share → Add to Home Screen.</p></div>`);}

function startPractice(queue=adaptiveQuestions(questions,state),mode='practice',timed=false,planTask=null){if(!queue.length){toast('No questions in this set yet. Try the full bank.');return;}highlightSelection=null;const dailyMultiplier=mode==='daily'&&!state.dailyAwards.includes(dateKey())?2:1;practice={queue:queue.map(q=>q.id),index:0,mode,timed,planTask,started:Date.now(),questionStarted:Date.now(),lastAttemptSeconds:0,hiddenMs:0,hiddenSince:null,seconds:600,selected:null,failures:0,solved:false,revealed:false,hints:[],waitingHint:false,eliminated:[],eliminateMode:false,results:[],attempts:[],xpStart:state.xp,levelStart:level(),notifiedLevel:level(),multiplier:dailyMultiplier};renderPractice(true);if(timed){practiceTimer=setInterval(()=>{if(!practice)return;const remaining=Math.max(0,600-Math.floor((Date.now()-practice.started)/1000));practice.seconds=remaining;const clock=$('#practice-clock');if(clock){clock.textContent=`${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')}`;clock.classList.toggle('urgent',remaining<60);}if(!remaining)finishPractice(true);},1000);}}

function renderPractice(initial=false){if(!practice)return;const p=practice,q=byId(p.queue[p.index]),done=p.solved||p.revealed,last=p.attempts.at(-1),annotation=state.annotations[q.id]??{};const solution=reviewAllowed(p.failures)&&done;const html=`<div class="practice-topbar"><a href="#home" class="practice-brand" tabindex="-1">${logo}<span>orbit.</span></a><span class="practice-mode">${({daily:'DAILY CHALLENGE · '+p.multiplier+'× XP',boss:'BOSS FIGHT',sprint:'TIMED SPRINT',friend:'FRIEND CHALLENGE',plan:'PERSONAL STUDY PLAN',practice:'ADAPTIVE PRACTICE'})[p.mode]}</span><span class="practice-counter">${p.index+1} <small>/ ${p.queue.length}</small></span>${p.timed?`<span class="practice-clock" id="practice-clock">${Math.floor(p.seconds/60)}:${String(p.seconds%60).padStart(2,'0')}</span>`:''}<button class="icon-button" data-action="end-practice" aria-label="End practice">${icon('close')}</button></div>${progressBar(p.index,p.queue.length)}<div class="practice-layout"><div class="practice-question">${toolkit(q,p,state)}<div class="practice-question-meta"><span>${q.id} <i>·</i> ${q.skill}</span><button class="icon-button ${state.bookmarks.includes(q.id)?'saved':''}" data-action="practice-bookmark" aria-label="Save this question">${icon('bookmark')}</button></div>${q.passage?`<div class="passage" id="reading-passage">${highlightedPassage(q.passage,annotation.highlights??[])}</div>`:''}${equationBlock(q)}<h2 class="question-stem">${esc(q.prompt)}</h2><fieldset class="answer-options"><legend class="sr-only">Choose your answer</legend>${q.choices.map((choice,i)=>`<div class="answer-row ${p.eliminated.includes(i)?'eliminated':''}"><label class="answer-option ${p.selected===i?'selected':''} ${done&&i===q.answer?'correct-option':''} ${last&&!last.correct&&last.choice===i?'incorrect-option':''}"><input type="radio" name="answer" value="${i}" ${p.selected===i?'checked':''} ${done||p.eliminated.includes(i)?'disabled':''}><span class="answer-key">${i+1}</span><span>${esc(choice)}</span>${done&&i===q.answer?icon('check'):''}</label>${p.eliminateMode||p.eliminated.includes(i)?`<button class="eliminate-choice" data-action="eliminate-choice" data-choice="${i}" aria-label="${p.eliminated.includes(i)?'Restore':'Cross out'} choice ${i+1}" aria-pressed="${p.eliminated.includes(i)}">${p.eliminated.includes(i)?'↶':'×'}</button>`:''}</div>`).join('')}</fieldset>${p.solved?`<div class="answer-feedback success">${icon('check')}<div><strong>That’s it. You made the connection.</strong><span>${p.attempts.length===1?'First-try win.':`You got there in ${p.attempts.length} attempts.`}</span></div></div>`:p.failures?`<div class="answer-feedback retry">${icon('spark')}<div><strong>${p.failures>=2?'Full review is unlocked.':'Not quite. Keep your thinking going.'}</strong><span>${p.failures>=2?'Try again, or review the explanation below.':'A hint can help. The answer stays hidden.'}</span></div></div><label class="error-type-label">What happened? <select id="attempt-error-type" aria-label="Label the likely error"><option value="${esc(last.errorType)}">${esc(last.errorType)} (suggested)</option>${['Sign error','Arithmetic','Misread condition','Wrong quantity','Method or arithmetic','Time pressure','Unsure'].filter(x=>x!==last.errorType).map(x=>`<option>${x}</option>`).join('')}</select></label>`:''}${solution?`<details class="solution-review" ${p.revealed?'open':''}><summary>Understand the solution ${icon('down')}</summary><ol>${q.workedSteps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol><div class="wrong-choice-notes"><h3>Why each other choice is wrong</h3>${q.wrongChoiceFeedback.map((f,i)=>i!==q.answer?`<div><strong>Choice ${i+1}: ${esc(q.choices[i])}</strong><p>${esc(f.reason)}</p><span>${esc(f.type)}</span></div>`:'').join('')}</div></details>`:p.failures>=2?'<button class="review-solution-button" data-action="review-solution">Review the step-by-step explanation</button>':''}<div class="practice-actions">${done?'<span class="muted small">Bring that idea to the next question.</span>':'<button class="text-link muted" data-action="skip-question">Skip for now</button>'}<button class="button primary" data-action="${done?'next-question':'submit-answer'}" ${!done&&p.selected===null?'disabled':''}>${done?(p.index===p.queue.length-1?'See my results':'Next question'):'Check answer'} ${icon('arrow')}</button></div><div class="keyboard-note"><span><kbd>1</kbd>–<kbd>4</kbd> to choose</span><span><kbd>Enter</kbd> ${done?'to continue':'to check'}</span></div></div><aside class="practice-tutor"><div class="tutor-sidebar-header"><span class="tutor-avatar">${icon('spark')}</span><div><h3>Orbit bank tutor</h3><small>SAT only · answer-blind · on-device</small></div></div><div class="tutor-level-dots">${[1,2,3].map(n=>`<span class="${p.hints.some(h=>h.level>=n)?'lit':''}">${n}</span>`).join('')}<span>THE NEXT STEP IS YOURS</span></div>${p.hints.length?p.hints.map(h=>`<div class="practice-hint"><div class="hint-level">${h.teach?'TEACH MODE':`LEVEL ${h.level}`} · ${esc(h.title)}</div><p>${esc(h.message)}</p><span>${esc(h.followUp)}</span></div>`).join(''):`<div class="tutor-idle"><div class="idle-spark">✦</div><h3>Give your brain<br>the first move.</h3><p>Try an answer. If it misses, we’ll work through the idea together.</p></div>`}<button class="button secondary hint-button" data-action="practice-hint" ${!p.failures||p.solved||p.waitingHint?'disabled':''}>${icon('chat')}${p.waitingHint?'Thinking…':p.hints.length?'A little more help':'Get a hint'}</button><button class="teach-button" data-action="practice-teach" ${!p.failures||p.solved||p.waitingHint?'disabled':''}>Explain like I’m teaching a 1st grader</button><details class="tool-tips"><summary>Tools & pacing tips ↓</summary>${q.desmosTip?`<p><b>Desmos move</b>${esc(q.desmosTip)}</p>`:''}<p><b>Pacing</b>${esc(q.pacingTip)}</p></details><div class="guardrail-note">${icon('info')}Only the stem, your incorrect response, and answer-free scaffolds reach my worker. Never choices or the key.</div></aside></div>`;if(initial)openModal(html,true);else $('.modal').innerHTML=html;}

function recordAttempt(q,choice,correct){const now=Date.now(),old=state.answers[q.id]??{attempts:0,failedAttempts:0,everCorrect:false,completed:false};let amount=correct?(old.everCorrect?0:(old.attempts?15:20)):(old.attempts?0:5);amount*=practice.multiplier;awardXp(state,amount,practice.mode,now);const assisted=practice.hints.length>0,elo=updateElo(state,q,correct,assisted),seconds=questionSeconds(),delta=Math.max(0,seconds-practice.lastAttemptSeconds),errorType=correct?null:classifyError(q,choice);practice.lastAttemptSeconds=seconds;state.answers[q.id]={...old,attempts:old.attempts+1,failedAttempts:old.failedAttempts+(correct?0:1),everCorrect:old.everCorrect||correct,completed:old.completed||correct,latestCorrect:correct,lastChoice:choice,lastAt:now};const entry={id:q.id,revision:q.revision,choice,correct,xp:amount,ts:now,mode:practice.mode,hints:practice.hints.length,elo:elo.after,timeSeconds:delta,questionSeconds:seconds,errorType,errorSource:correct?null:'choice-rule'};state.log.push(entry);scheduleReview(state,q.id,correct,now);noteActivity(state);practice.attempts.push({choice,correct,errorType,timeSeconds:delta,logIndex:state.log.length-1});save();}

function submitAnswer(){if(!practice||practice.selected===null||practice.solved||practice.revealed)return;const q=byId(practice.queue[practice.index]),correct=practice.selected===q.answer;recordAttempt(q,practice.selected,correct);if(correct)practice.solved=true;else practice.failures++;renderPractice();if(correct&&level()>practice.notifiedLevel){practice.notifiedLevel=level();showLevelUp();}}
function reviewSolution(){if(!practice||!reviewAllowed(practice.failures))return;practice.revealed=true;const q=byId(practice.queue[practice.index]);state.answers[q.id].completed=true;save();renderPractice();}
function storeQuestionResult(){const p=practice;if(!p||p.results.some(r=>r.index===p.index))return;p.results.push({id:p.queue[p.index],index:p.index,attempts:p.attempts.length,correct:p.solved,firstTry:p.attempts.length===1&&p.solved,reviewed:p.revealed,skipped:!p.solved&&!p.revealed,seconds:questionSeconds(),responses:p.attempts.map(a=>({...a}))});}

function nextQuestion(){if(!practice)return;storeQuestionResult();if(practice.index===practice.queue.length-1){finishPractice(true);return;}Object.assign(practice,{index:practice.index+1,selected:null,failures:0,solved:false,revealed:false,hints:[],waitingHint:false,attempts:[],eliminated:[],eliminateMode:false,questionStarted:Date.now(),lastAttemptSeconds:0,hiddenMs:0,hiddenSince:null});highlightSelection=null;renderPractice();$('.question-stem')?.scrollIntoView({block:'nearest'});}

function finishPractice(finished){if(!practice)return;closeTool();clearInterval(practiceTimer);storeQuestionResult();const p=practice;let bonus=0;const allAttempted=p.results.length===p.queue.length&&p.results.every(r=>r.attempts>0);if(p.mode==='daily'&&finished&&allAttempted&&!state.dailyAwards.includes(dateKey()))state.dailyAwards.push(dateKey());if(p.mode==='boss'&&p.results.filter(r=>r.correct&&!r.reviewed).length===5&&!state.sessions.some(s=>s.mode==='boss'&&dateKey(new Date(s.ts))===dateKey()&&s.bonus)){bonus=75;awardXp(state,bonus,'boss-clear');}const record={id:crypto.randomUUID?.()??String(Date.now()),mode:p.mode,label:p.planTask?.title,planTask:p.planTask,ts:Date.now(),total:p.queue.length,attempted:p.results.filter(r=>r.attempts).length,correct:p.results.filter(r=>r.correct).length,firstTry:p.results.filter(r=>r.firstTry).length,xp:state.xp-p.xpStart,bonus,finished:finished&&allAttempted,seconds:Math.floor((Date.now()-p.started)/1000),activeSeconds:p.results.reduce((n,r)=>n+r.seconds,0),questions:p.queue,results:p.results};record.analytics=sessionAnalytics(record,questions.concat(archivedQuestions));const skills=new Map();for(const result of record.results.filter(r=>r.attempts)){const skill=byId(result.id).skill,item=skills.get(skill)??{total:0,first:0};item.total++;item.first+=Number(result.firstTry);skills.set(skill,item);}const weakest=[...skills].filter(([,v])=>v.first<v.total).sort((a,b)=>a[1].first/a[1].total-b[1].first/b[1].total)[0];record.weakest=weakest?weakest[0]:'No weak spot this run';if(p.planTask&&record.finished&&p.planTask.date===dateKey())state.planCompletions[dateKey()]={...p.planTask,completed:true,sessionId:record.id};practice=null;if(record.attempted)state.sessions.push(record);save();renderApp();if(!record.attempted){closeModal();return;}showResults(record);if(level()>p.notifiedLevel)showLevelUp();}

function showLevelUp(){if($('#level-up'))return;const node=document.createElement('div');node.id='level-up';node.className='level-up';node.setAttribute('role','status');node.innerHTML=`<span>✦</span><div>LEVEL UP<strong>Level ${level()}</strong></div><span>✦</span>`;document.body.append(node);setTimeout(()=>node.remove(),3200);}
function requestHint(q,choice,callback,simple=false){const worker=simple?teachWorker:tutorWorker;if(!worker){toast('The tutor worker is unavailable. Reload Orbit in a supported browser.');callback(null);return;}worker.onmessage=event=>{if(event.data.ok)callback({...event.data.hint,teach:simple});else{toast(event.data.error||'The tutor could not prepare a hint.');callback(null);}};worker.onerror=()=>{toast('The tutor could not load. Reload once while online.');callback(null);};worker.postMessage(buildTutorPayload(q,choice,{simple}));}

function practiceHint(){if(!practice||!practice.failures||practice.solved||practice.waitingHint)return;const q=byId(practice.queue[practice.index]),choice=practice.attempts.filter(a=>!a.correct).at(-1).choice;const session=practice,index=practice.index;practice.waitingHint=true;renderPractice();requestHint(q,choice,h=>{if(practice!==session||practice.index!==index)return;practice.waitingHint=false;if(h)practice.hints.push(h);renderPractice();});}
function drawResultsCard(s){const canvas=$('#results-canvas');if(!canvas)return;const ctx=canvas.getContext('2d');ctx.fillStyle='#101423';ctx.fillRect(0,0,1080,640);const gradient=ctx.createRadialGradient(970,30,0,970,30,650);gradient.addColorStop(0,'#352955');gradient.addColorStop(1,'#101423');ctx.fillStyle=gradient;ctx.fillRect(0,0,1080,640);for(let i=0;i<55;i++){ctx.fillStyle=i%3?'#6b6885':'#d2c8f4';ctx.beginPath();ctx.arc((i*137+41)%1080,(i*83+17)%640,i%4===0?2:1,0,Math.PI*2);ctx.fill();}ctx.strokeStyle='#75649b';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(950,120,155,58,-.5,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#ae97da';ctx.beginPath();ctx.arc(950,120,62,0,Math.PI*2);ctx.fill();ctx.fillStyle='#c9f49b';ctx.font='bold 32px sans-serif';ctx.fillText('orbit.',60,67);ctx.fillStyle='#a89dbb';ctx.font='bold 17px sans-serif';ctx.fillText('MISSION COMPLETE  /  SAT PRACTICE',60,115);ctx.fillStyle='#f5f3ff';ctx.font='bold 52px sans-serif';ctx.fillText(s.firstTry===s.total?'FLAWLESS FLIGHT.':'MOMENTUM UNLOCKED.',60,195);ctx.fillStyle='#b6b4c8';ctx.font='23px sans-serif';ctx.fillText(`${state.name} · ${s.attempted} questions attempted`,60,242);ctx.fillStyle='#c9f49b';ctx.font='bold 86px sans-serif';ctx.fillText(`${s.firstTry}/${s.total}`,60,370);ctx.fillStyle='#e0d0ff';ctx.fillText(`+${s.xp}`,435,370);ctx.fillStyle='#a8acbd';ctx.font='20px sans-serif';ctx.fillText('FIRST-TRY CORRECT',60,410);ctx.fillText('XP EARNED',435,410);ctx.strokeStyle='#33374e';ctx.beginPath();ctx.moveTo(60,456);ctx.lineTo(1020,456);ctx.stroke();ctx.fillStyle='#9ba1b6';ctx.font='bold 16px sans-serif';ctx.fillText('NEXT FOCUS',60,502);ctx.fillStyle='#f4f2ff';ctx.font='bold 28px sans-serif';ctx.fillText(s.weakest,60,543);ctx.fillStyle='#a8acbd';ctx.font='17px sans-serif';ctx.fillText('Small steps. Stellar scores.  ·  Original SAT-style practice',60,600);}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Link copied. This site requires access permission.');}catch{openModal(`${modalHeader('Your challenge link')}<label class="share-link-label">Copy this link<input value="${esc(text)}" readonly onclick="this.select()"></label>`);}}
function reviewCard(result){const beforeLevel=level();const q=getCardDeck()[cardIndex];if(!q||!cardFlipped)return;const today=dateKey(),already=state.reviews.some(r=>r.id===q.id&&dateKey(new Date(r.ts))===today);state.reviews.push({id:q.id,ts:Date.now(),result});scheduleReview(state,q.id,result==='got');noteActivity(state);if(!already)awardXp(state,5,'flashcard');const unique=new Set(state.reviews.filter(r=>dateKey(new Date(r.ts))===today).map(r=>r.id));if(unique.size>=3&&!state.dailyAwards.includes('cards-'+today)){awardXp(state,30,'flashcard-quest');state.dailyAwards.push('cards-'+today);toast('Three-card quest complete. +30 XP!');}save();if(level()>beforeLevel)showLevelUp();cardFlipped=false;if(cardDeck!=='due')cardIndex++;renderApp();}
function bookmark(id){state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();}
function startBoss(){const missed=questions.filter(q=>state.answers[q.id]?.failedAttempts>0);if(missed.length<5){toast(`Boss Fights unlock after 5 different missed questions. You have ${missed.length}.`);return;}startPractice(adaptiveQuestions(missed,state,5),'boss');}
function downloadBlob(blob,filename){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}


function questionSeconds(){if(!practice)return 0;const p=practice,hidden=p.hiddenMs+(p.hiddenSince?Date.now()-p.hiddenSince:0);return Math.max(0,Math.round((Date.now()-p.questionStarted-hidden)/1000));}
function showResults(record){openModal(`${modalHeader('Mission complete.','Every attempt adds to your orbit.')}<div class="results-screen"><div class="result-rank">${icon('rocket')}</div><div class="eyebrow">${record.firstTry===record.total?'FLAWLESS FLIGHT':'MOMENTUM UNLOCKED'}</div><h2>${record.firstTry===record.total?'You’re on another level.':'One step closer.'}</h2><div class="results-stats"><div><strong>${record.firstTry}<small>/${record.total}</small></strong><span>First-try correct</span></div><div><strong class="mint-text">+${record.xp}</strong><span>XP earned</span></div><div><strong>${record.correct}</strong><span>Solved</span></div></div><div class="weakest-skill"><span>YOUR NEXT FOCUS</span><strong>${esc(record.weakest||'Review your session')}</strong><small>${record.attempted} attempted · ${record.total-record.attempted} skipped${record.finished?'':' · partial run'}</small></div>${analyticsPanel(record,questions.concat(archivedQuestions))}<div class="result-card-preview"><canvas id="results-canvas" width="1080" height="640" aria-label="Shareable game results card"></canvas></div><div class="result-share-actions"><button class="button secondary" data-action="download-card">${icon('download')} Save results card</button><button class="button secondary" data-action="copy-challenge" data-session="${record.id}">${icon('link')}Copy link to challenge a friend with the same ${record.total} questions</button></div><button class="button primary result-done" data-action="close-modal">Back to my orbit ${icon('arrow')}</button><p class="small muted">Challenge links share question IDs and require access to this site. Student profiles stay on each device.</p></div>`);drawResultsCard(record);}
function openTool(title,html){if($('#tool-root'))closeTool();toolLastFocus=document.activeElement;let root=document.createElement('div');root.id='tool-root';root.innerHTML=`<div class="tool-scrim"><section class="tool-modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header><h2>${title}</h2><button class="icon-button" data-action="close-tool" aria-label="Close ${esc(title)}">${icon('close')}</button></header>${html}</section></div>`;document.body.append(root);if($('.modal'))$('.modal').inert=true;else $('#app').inert=true;root.querySelector('button')?.focus();}
function closeTool(){const root=$('#tool-root');if(!root)return;root.remove();if($('.modal'))$('.modal').inert=false;else $('#app').inert=false;toolLastFocus?.focus?.();}
function captureHighlight(){const selection=window.getSelection?.(),passage=$('#reading-passage');if(!selection?.rangeCount||!passage||selection.isCollapsed)return;const range=selection.getRangeAt(0);if(!passage.contains(range.startContainer)||!passage.contains(range.endContainer))return;const before=range.cloneRange();before.selectNodeContents(passage);before.setEnd(range.startContainer,range.startOffset);highlightSelection=[before.toString().length,before.toString().length+range.toString().length];}
function addHighlight(){if(!practice)return;captureHighlight();if(!highlightSelection){toast('Select a phrase in the reading passage, then tap Highlight selection.');return;}const id=practice.queue[practice.index];state.annotations[id]??={highlights:[]};state.annotations[id].highlights??=[];state.annotations[id].highlights.push(highlightSelection);highlightSelection=null;save();renderPractice();}
function teachPractice(){if(!practice?.failures||practice.solved||practice.waitingHint)return;const session=practice,index=practice.index,q=byId(practice.queue[index]),choice=practice.attempts.filter(a=>!a.correct).at(-1).choice;practice.waitingHint=true;renderPractice();requestHint(q,choice,h=>{if(practice!==session||practice.index!==index)return;practice.waitingHint=false;if(h)practice.hints.push(h);renderPractice();},true);}
function onboard(){openModal(`${modalHeader('Hey, curious mind. What should we call you?','Your home, plan, and results will be personal to you.')}<form id="onboard-form" class="settings-form"><label>Your name or nickname<input name="name" maxlength="40" autocomplete="given-name" placeholder="e.g. Alex" required></label><label>Test date <small>(optional)</small><input name="testDate" type="date"></label><button class="button primary">Build my orbit →</button><p class="muted small">Saved on this device. No email, account, or API key needed.</p></form>`);}
function addStudentDialog(){openModal(`${modalHeader('A new learner. A fresh start.','A nickname is enough for a local student profile.')}<form id="add-student-form" class="settings-form"><label>Student nickname<input name="name" maxlength="40" required autocomplete="off"></label><label>Test date <small>(optional)</small><input type="date" name="testDate"></label><button class="button primary">Add student profile →</button><p class="muted small">Profiles are stored only in this browser. Other phones do not automatically sync here.</p></form>`);}
function profilePicker(){openModal(`${modalHeader('Whose orbit are we in?','Switching keeps each learner’s work separate.')}<div class="profile-picker">${roster.students.map(student=>`<button data-action="switch-student" data-id="${student.id}"><span>${esc(student.name)}</span><small>${student.id===roster.activeId?'Active profile':student.role==='owner'?'Your own practice':'Student profile'}</small></button>`).join('')}<button class="button secondary" data-action="add-student">+ Add student</button><a class="text-link" href="/tutor">Open tutor dashboard →</a></div>`);}
function switchStudent(id){const profile=roster.students.find(s=>s.id===id);if(!profile)return;save();roster.activeId=id;state=normalizeStudent(profile.data);chatMessages=[];resetTutorWorkers();reconcileFreezes(state);save();closeModal();planOffset=0;setView('home');toast(`Now studying as ${state.name}.`);}
function exportStats(){const profile=view==='tutor'&&tutorSelectedId?roster.students.find(p=>p.id===tutorSelectedId):roster.students.find(p=>p.id===roster.activeId);const data=profile?.data??state;downloadBlob(new Blob([JSON.stringify({...bankStats,prediction:predictScores(data.log,questions),profile:{name:data.name,id:profile?.id},updatedAt:new Date().toISOString()},null,2)],{type:'application/json'}),'stats.json');}

document.addEventListener('click',event=>{
 const route=event.target.closest('[data-route]');if(route&&!practice){event.preventDefault();setView(route.dataset.route);return;}const direct=event.target.closest('a[href="/plan"],a[href="/tutor"],a[href="/guide"]');if(direct&&!practice){event.preventDefault();setView(direct.getAttribute('href').slice(1));return;}
 const button=event.target.closest('[data-action]');if(!button||button.disabled)return;const action=button.dataset.action;event.preventDefault();
 switch(action){
 case'theme':applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');renderApp();break;
 case'profiles':profilePicker();break;
 case'add-student':addStudentDialog();break;
 case'switch-student':switchStudent(button.dataset.id);break;
 case'student-report':tutorSelectedId=button.dataset.id;renderApp();$('.student-report-heading')?.scrollIntoView({block:'start'});break;
 case'export-student':{const profile=roster.students.find(s=>s.id===button.dataset.id);if(profile)downloadBlob(new Blob([JSON.stringify({format:'orbit-student-v1',name:profile.name,data:profile.data},null,2)],{type:'application/json'}),'orbit-student.json');break;}
 case'student-session-report':{const profile=roster.students.find(s=>s.id===button.dataset.id),session=profile?.data.sessions.find(s=>s.id===button.dataset.session);if(session)openModal(`${modalHeader(`${esc(profile.name)}: study-set report`)}${analyticsPanel(session,questions.concat(archivedQuestions))}`);break;}
 case'session-report':{const session=state.sessions.find(s=>s.id===button.dataset.session);if(session)openModal(`${modalHeader('Your study-set report')}${analyticsPanel(session,questions.concat(archivedQuestions))}`);break;}
 case'plan-page':planOffset=Math.max(0,planOffset+Number(button.dataset.offset));renderApp();window.scrollTo(0,0);break;
 case'plan-run':{const task=buildStudyPlan(state,questions).days.find(t=>t.date===button.dataset.date);if(task?.ids.length&&!task.locked)startPractice(task.ids.map(byId),task.type==='boss'?'boss':'plan',false,task);break;}
 case'guide-tab':guideTab=button.dataset.tab;renderApp();break;
 case'export-stats':exportStats();break;
 case'copy-site-link':copyText('https://orbit.bronzekite16385.chatgpt.site');break;
 case'calculator':openTool('Desmos calculator',calculatorHTML(navigator.onLine!==false));break;
 case'reference':openTool('Formula reference',referenceHTML());break;
 case'close-tool':closeTool();break;
 case'highlight':addHighlight();break;
 case'clear-highlights':if(practice){state.annotations[practice.queue[practice.index]]={highlights:[]};save();renderPractice();}break;
 case'eliminator':if(practice){practice.eliminateMode=!practice.eliminateMode;renderPractice();}break;
 case'eliminate-choice':if(practice&&!practice.solved&&!practice.revealed){const i=Number(button.dataset.choice);practice.eliminated=practice.eliminated.includes(i)?practice.eliminated.filter(x=>x!==i):[...practice.eliminated,i];if(practice.eliminated.includes(practice.selected))practice.selected=null;renderPractice();}break;
 case'mark-review':if(practice){const id=practice.queue[practice.index];state.markedForReview=state.markedForReview.includes(id)?state.markedForReview.filter(x=>x!==id):[...state.markedForReview,id];save();renderPractice();}break;
 case'practice-teach':teachPractice();break;
 case'coach-teach':{const q=byId(button.dataset.id);chatAdd('user','Explain this like I’m teaching a 1st grader.');requestHint(q,Number(button.dataset.choice),h=>h&&chatAdd('assistant',h.message+'\n'+h.followUp,{level:h.level,title:h.title}),true);break;}

 case'menu':$('#sidebar').classList.toggle('mobile-open');break;
 case'settings':settings();break;
 case'close-modal':closeModal();break;
 case'practice':startPractice();break;
 case'subject-practice':startPractice(adaptiveQuestions(questions.filter(q=>q.subject===button.dataset.subject),state));break;
 case'daily':startPractice(dailyQuestions(questions),'daily');break;
 case'boss':startBoss();break;
 case'sprint':startPractice(adaptiveQuestions(questions,state),'sprint',true);break;
 case'go-cards':setView('cards');break;
 case'open-question':startPractice([byId(button.dataset.id)]);break;
 case'filtered-practice':startPractice(adaptiveQuestions(filteredBank(),state));break;
 case'filter-subject':filters.subject=button.dataset.subject;filters.domain='All';filters.page=1;renderApp();break;
 case'filter-saved':filters.saved=button.dataset.key;filters.page=1;$('#bank-results').innerHTML=renderBankResults();break;
 case'bank-page':filters.page+=Number(button.dataset.offset);$('#bank-results').innerHTML=renderBankResults();$('#bank-results').scrollIntoView({block:'start'});break;
 case'clear-filters':filters={subject:'All',difficulty:'All',domain:'All',search:'',saved:'all',page:1};renderApp();break;
 case'bookmark':bookmark(button.dataset.id);if(view==='bank')$('#bank-results').innerHTML=renderBankResults();else renderApp();break;
 case'practice-bookmark':bookmark(practice.queue[practice.index]);renderPractice();break;
 case'flip-card':cardFlipped=!cardFlipped;renderApp();break;
 case'card-next':cardIndex++;cardFlipped=false;renderApp();break;
 case'card-prev':cardIndex=(cardIndex-1+getCardDeck().length)%getCardDeck().length;cardFlipped=false;renderApp();break;
 case'review-card':reviewCard(button.dataset.result);break;
 case'submit-answer':submitAnswer();break;
 case'next-question':case'skip-question':nextQuestion();break;
 case'end-practice':finishPractice(false);break;
 case'review-solution':reviewSolution();break;
 case'practice-hint':practiceHint();break;
 case'history-tab':historyTab=button.dataset.tab;renderApp();break;
 case'history-page':historyPage+=Number(button.dataset.offset);renderApp();$('.history-panel').scrollIntoView();break;
 case'board-scope':boardScope=button.dataset.scope;renderApp();break;
 case'coach-plan':chatAdd('user','Build my study plan.');chatAdd('assistant',studyPlan());break;
 case'coach-how':chatAdd('user','How do your hints work?');chatAdd('assistant','Level 1 refreshes the concept. Level 2 checks your selected response for a likely mistake. Level 3 walks through the first action, leaving the rest to you. The worker receives only the question, your incorrect response, and answer-free scaffolds. A full solution is available in practice after two missed attempts. A correct response confirms your choice without opening the worked solution early.');break;
 case'coach-hint':{const q=byId(button.dataset.id);chatAdd('user',`Help me with ${q.id}.`);requestHint(q,Number(button.dataset.choice),h=>{if(h)chatAdd('assistant',h.message+'\n'+h.followUp,{level:h.level,title:h.title});});break;}
 case'download-card':{const canvas=$('#results-canvas');canvas?.toBlob(blob=>blob&&downloadBlob(blob,'orbit-mission.png'),'image/png');break;}
 case'copy-challenge':{const s=state.sessions.find(s=>s.id===button.dataset.session);const url=new URL(location.origin);url.searchParams.set('challenge',s.questions.join('.'));copyText(url.href);break;}
 case'export-progress':downloadBlob(new Blob([JSON.stringify({format:'orbit-student-v1',name:state.name,data:state},null,2)],{type:'application/json'}),'orbit-progress.json');break;
 case'freezes':openModal(`${modalHeader('An occasional pause is human.')}<div class="info-modal"><span class="subject-icon blue">${icon('snow')}</span><h3>${state.freezes} streak freezes ready</h3><p>When enabled, a freeze automatically covers one missed day between study days. You start with two, and earn one back after each 7 distinct practice days, up to two.</p><p>Freeze days protect a streak but never count as actual practice days or earn XP. If a gap exceeds your available freezes, your streak restarts.</p><button class="button secondary" data-action="settings">Manage protection ${icon('arrow')}</button></div>`);break;
 case'tutor-info':openModal(`${modalHeader('A tutor that leaves the thinking to you.')}<div class="info-modal"><p>Orbit’s tutor is an on-device, rule-based adaptive engine in a separate Web Worker. It only coaches allowlisted Orbit bank questions. Teach Mode uses simple words for the same concept. No generative AI model is connected, and no API key is needed.</p><p>The worker receives exactly three learning inputs: the question stem, your incorrect response, and answer-free scaffolding steps. It never receives choices, answer indices, final answers, or full worked solutions.</p><p>In scored practice, full worked review stays hidden until two failed attempts. A correct response confirms your selection without opening the full solution early. Flashcards are a separate, explicitly revealable study mode.</p><p>The system prompt repeats these rules, but the actual protection comes from code and the narrow message boundary. This is a teaching guardrail, not exam-security protection against inspecting browser source.</p></div>`);break;
 case'about':openModal(`${modalHeader('A little better, every day.')}<div class="info-modal"><p>Orbit is an independent SAT practice project: 500 original SAT-style questions across 29 primary skills and 8 domains, including 45 multi-step hard math items. The bank includes parameter variants, two-step explanations, and automated checks.</p><p>This project is not affiliated with College Board or MIT. Practice difficulty and local ELO ratings are not calibrated SAT score predictions.</p><p>Your full history, XP, local demo leaderboard, and settings stay in this browser. Export progress to keep a copy. Challenge links share only the selected question IDs.</p><a href="#science" class="text-link" data-action="go-science">Explore the learning research ${icon('arrow')}</a><div class="project-downloads"><a href="/README_FOR_MIT.md" download>Architecture notes ↗</a><a href="/stats.json" download>Bank statistics ↗</a><a href="/orbit-source.zip" download>Download source project ↗</a></div></div>`);break;
 case'go-science':closeModal();setView('science');break;
 case'help':openModal(`${modalHeader('Your controls, cadet.')}<div class="info-modal"><div class="shortcut-row"><span>Choose an answer</span><span><kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> <kbd>4</kbd></span></div><div class="shortcut-row"><span>Check / next question</span><kbd>Enter</kbd></div><div class="shortcut-row"><span>Flip a flashcard</span><kbd>Space</kbd></div><div class="shortcut-row"><span>Close a dialog</span><kbd>Esc</kbd></div><p>After a miss, choose again and check. Get up to three increasingly specific hint levels. Solution review unlocks after two failed attempts.</p><button class="button secondary" data-action="install">${icon('download')} Install for offline practice</button></div>`);break;
 case'install':if(installPrompt){installPrompt.prompt();installPrompt=null;}else{toast('On iPhone: Safari → Share → Add to Home Screen. On desktop: use your browser’s install icon.');}break;
 case'accept-challenge':{const ids=button.dataset.ids.split('.');closeModal();startPractice(ids.map(byId),'friend');break;}
 }
});
document.addEventListener('change',event=>{const t=event.target;if(t.id==='attempt-error-type'&&practice){const attempt=practice.attempts.at(-1);if(attempt&&!attempt.correct){attempt.errorType=t.value;state.log[attempt.logIndex].errorType=t.value;state.log[attempt.logIndex].errorSource='self-report';save();}}if(t.id==='student-import'){const file=t.files?.[0];if(file){if(file.size>8000000){toast('Choose an Orbit export under 8 MB.');return;}file.text().then(text=>{const profile=importStudent(roster,JSON.parse(text));save();tutorSelectedId=profile.id;renderApp();toast('Student results imported locally.');}).catch(error=>toast(error.message));}}if(t.name==='answer'&&practice){practice.selected=Number(t.value);renderPractice();$(`input[name="answer"][value="${t.value}"]`)?.focus();}if(t.id==='difficulty-filter'||t.id==='domain-filter'){filters[t.id==='difficulty-filter'?'difficulty':'domain']=t.value;filters.page=1;$('#bank-results').innerHTML=renderBankResults();}if(t.id==='card-deck'){cardDeck=t.value;cardIndex=0;cardFlipped=false;renderApp();}if(t.id==='history-filter'){historyFilter=t.value;historyPage=1;renderApp();}});
document.addEventListener('input',event=>{if(event.target.id==='bank-search'){filters.search=event.target.value;filters.page=1;$('#bank-results').innerHTML=renderBankResults();}});
document.addEventListener('submit',event=>{if(event.target.id==='basic-calculator'){event.preventDefault();try{$('#calculator-output').textContent=String(calculate(new FormData(event.target).get('expression')));}catch(error){$('#calculator-output').textContent=error.message;}return;}if(event.target.id==='plan-form'){event.preventDefault();const value=String(new FormData(event.target).get('testDate'));if(!/^\d{4}-\d{2}-\d{2}$/.test(value))return;state.testDate=value;planOffset=0;save();renderApp();toast('Your plan now follows this test date.');return;}if(event.target.id==='add-student-form'){event.preventDefault();const values=new FormData(event.target);const student=createStudent(roster,values.get('name'),String(values.get('testDate')||''));save();tutorSelectedId=student.id;closeModal();setView('tutor');toast('Student profile added. Choose “Study as student” to begin.');return;}if(event.target.id==='onboard-form'){event.preventDefault();const values=new FormData(event.target);state.name=String(values.get('name')).trim().slice(0,40)||'Student';state.testDate=String(values.get('testDate')||'');state.onboarded=true;save();closeModal();renderApp();toast(`Welcome to your orbit, ${state.name}.`);return;}if(event.target.id==='settings-form'){event.preventDefault();const data=new FormData(event.target);state.name=String(data.get('name')).trim().slice(0,40)||'You';state.onboarded=true;state.testDate=String(data.get('testDate')||'');applyTheme(String(data.get('theme')||themePreference));state.goal=Number(data.get('goal'));state.autoFreeze=data.has('freeze');save();closeModal();renderApp();toast('Your space, your rules. Settings saved.');}if(event.target.id==='coach-form'){event.preventDefault();const text=$('#coach-input').value.trim();if(!text)return;chatAdd('user',text);if(/plan|study|weak|focus/i.test(text))chatAdd('assistant',studyPlan());else if(/hint|help|explain|stuck|M\d{3}|R\d{3}|H\d{3}/i.test(text)){const requested=text.match(/[MRH]\d{3}/i)?.[0]?.toUpperCase();const miss=state.log.slice().reverse().find(a=>!a.correct&&(!requested||a.id===requested));if(miss)requestHint(byId(miss.id),miss.choice,h=>h&&chatAdd('assistant',h.message+'\n'+h.followUp,{level:h.level,title:h.title}));else chatAdd('assistant','Try a practice question first. After an incorrect response, I can give a concept, a mistake check, and a first-step hint without seeing the final answer.');}else chatAdd('assistant','I only coach Orbit’s SAT question bank. I can plan practice from those skills or give a hint on a missed Orbit question. Try “Make a study plan” or “Give me a hint.”');}});
document.addEventListener('keydown',event=>{const typing=/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName)&&document.activeElement?.type!=='radio';if(event.key==='Escape'&&$('#tool-root')){event.preventDefault();closeTool();return;}if(event.key==='Escape'&&$('.modal')){event.preventDefault();closeModal();return;}if(event.key==='Tab'&&($('#tool-root')||$('.modal'))){const target=$('#tool-root .tool-modal')||$('.modal');const items=[...target.querySelectorAll('button:not([disabled]),input:not([disabled]),select,summary,a[href]')].filter(n=>n.offsetParent!==null&&n.tabIndex>=0);const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}if(typing||$('#tool-root'))return;if(practice){if(/^[1-4]$/.test(event.key)&&!practice.solved&&!practice.revealed){event.preventDefault();const index=Number(event.key)-1;if(!practice.eliminated.includes(index))practice.selected=index;renderPractice();}if(event.key==='Enter'&&(!document.activeElement?.matches('button')||document.activeElement.matches('[data-action=submit-answer],[data-action=next-question]'))){event.preventDefault();if(practice.solved||practice.revealed)nextQuestion();else submitAnswer();}}else if(view==='cards'&&event.code==='Space'&&!$('.modal')){event.preventDefault();cardFlipped=!cardFlipped;renderApp();}});
window.addEventListener('hashchange',()=>{if(practice)return;view=readRoute();if($('.modal'))closeModal();renderApp();window.scrollTo(0,0);});
window.addEventListener('popstate',()=>{if(!practice){view=readRoute();renderApp();}});
document.addEventListener('selectionchange',captureHighlight);
document.addEventListener('pointerdown',event=>{if(event.target.closest('[data-action=highlight]')){captureHighlight();event.preventDefault();}});
document.addEventListener('visibilitychange',()=>{if(!practice)return;if(document.hidden)practice.hiddenSince=Date.now();else if(practice.hiddenSince){practice.hiddenMs+=Date.now()-practice.hiddenSince;practice.hiddenSince=null;}});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});
renderApp();
if(!state.onboarded&&!new URLSearchParams(location.search).has('challenge')&&view!=='tutor')onboard();
if(freezeUsed)toast(`${freezeUsed} streak freeze${freezeUsed>1?'s':''} protected your momentum.`);
const challengeParam=new URLSearchParams(location.search).get('challenge');
if(challengeParam){const ids=challengeParam.split('.');if(ids.length>=1&&ids.length<=10&&new Set(ids).size===ids.length&&ids.every(byId)){openModal(`${modalHeader('A friend left you a challenge.','Same questions. Your own fresh start.')}<div class="info-modal friend-invite"><span class="subject-icon lavender">${icon('rocket')}</span><h3>${ids.length} questions. One friendly rematch.</h3><p>Your answers and progress stay on your device. This link does not contain your friend’s personal results.</p><button class="button primary" data-action="accept-challenge" data-ids="${ids.join('.')}">Challenge accepted ${icon('arrow')}</button></div>`);}else toast('That challenge link is incomplete. Try a fresh Daily Challenge.');}
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{console.info('Offline caching is unavailable in this browser session.');}));
